window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a5a6eb96d2826cba"]={"versions": [{"id": "FIG-a5a6eb96d2826cba", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (in einem mit <code>class Activity</code> betitelten Rahmen) des LIN Network Management (<code>LinNm</code>) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die übergeordneten Betriebsmodi des LIN-NM-Zustandsautomaten und deren Übergänge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände: <code>Bus Sleep Mode</code>, <code>Network Mode</code>.\n</li><li>Pseudozustände: Initialzustand <code>Power ON</code> (ausgefüllter Kreis), Endzustand <code>Power OFF</code> (umrandeter Punkt).\n</li><li>API-Funktionen / Trigger: <code>LinNm_init</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_PassiveStartUp</code>, <code>LinNm_NetworkRelease</code>.\n</li><li>Benachrichtigungen / Aktionen: <code>Initialization of Lin NM</code>, <code>Notify Network Mode</code>, <code>Notify Bus Sleep Mode</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Eintritt über <code>Power ON</code> mit Aufruf von <code>LinNm_init</code> führt mit der Aktion <code>/Initialization of Lin NM</code> in den Zustand <code>Bus Sleep Mode</code>.\n</li><li>Aus dem <code>Bus Sleep Mode</code> führt entweder der Aufruf <code>LinNm_PassiveStartUp</code> oder der Aufruf <code>LinNm_NetworkRequest</code> (mit Benachrichtigung <code>(Notify Network Mode)</code>) in den Zustand <code>Network Mode</code>.\n</li><li>Aus dem <code>Network Mode</code> führt der Aufruf <code>LinNm_NetworkRelease</code> mit der Benachrichtigung <code>(Notify Bus Sleep Mode)</code> zurück in den <code>Bus Sleep Mode</code>.\n</li><li>Aus dem <code>Bus Sleep Mode</code> führt das Ereignis <code>Power Off</code> in den Endzustand <code>Power OFF</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die obligatorische Betriebsmodi-Steuerung des LIN-NM. Implementierungen müssen sicherstellen, dass Netzwerkaktivierungen (<code>LinNm_NetworkRequest</code>, <code>LinNm_PassiveStartUp</code>) den Übergang in den <code>Network Mode</code> erzwingen und entsprechende Statusrückmeldungen an höhere Schichten (wie den NM-Interface / ComM) auslösen. Der Übergang zurück in den <code>Bus Sleep Mode</code> erfolgt über <code>LinNm_NetworkRelease</code>.</p>"}, {"id": "FIG-9a370cb9e0009c0d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm des LIN Network Management (<code>LinNm</code>) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die übergeordneten Betriebsmodi des LIN-NM-Zustandsautomaten sowie die zustandswechselnden Ereignisse, Bedingungen und Benachrichtigungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände: <code>Bus Sleep Mode</code>, <code>Network Mode</code>.\n</li><li>Pseudozustände: Initialzustand <code>Power ON</code> (ausgefüllter Kreis), Endzustand <code>Power OFF</code> (umrandeter Punkt).\n</li><li>API-Funktionen / Trigger / Timer-Events: <code>LinNm_Init</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_PassiveStartUp</code>, <code>LinNm_NetworkRelease</code>, <code>LinNmTimeoutTime elapsed</code>.\n</li><li>Wächterbedingung: <code>[Network not requested]</code>.\n</li><li>Benachrichtigungen / Aktionen: <code>Initialization of LinNm</code>, <code>Notify Network Mode</code>, <code>Notify Bus Sleep Mode</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Eintritt über <code>Power ON</code> mit <code>LinNm_Init</code> und Ausführung von <code>/Initialization of LinNm</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Vom <code>Bus Sleep Mode</code> wechselt das System über <code>LinNm_PassiveStartUp</code> oder über <code>LinNm_NetworkRequest /Notify Network Mode</code> in den <code>Network Mode</code>.\n</li><li>Vom <code>Network Mode</code> führt der Aufruf <code>LinNm_NetworkRelease /Notify Bus Sleep Mode</code> zurück in den <code>Bus Sleep Mode</code>.\n</li><li>Ein automatischer Übergang von <code>Network Mode</code> in den <code>Bus Sleep Mode</code> erfolgt, wenn die Bedingung <code>[Network not requested]</code> erfüllt ist und das Ereignis <code>/LinNmTimeoutTime elapsed</code> eintritt.\n</li><li>Vom <code>Bus Sleep Mode</code> führt das Ereignis <code>Power Off</code> in den Endzustand <code>Power OFF</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Zustandsübergänge des LIN-NM. Neben der expliziten Anforderung und Freigabe durch den Kommunikationsmanager wird ein automatischer Rückfallpfad bei Ausbleiben von Netzwerkanfragen (<code>[Network not requested]</code>) nach Ablauf des konfigurierbaren Timers <code>LinNmTimeoutTime</code> vorgeschrieben. Die Notifizierungen an den ComM bzw. das NM-Interface sind synchron zu den Zustandswechseln auszuführen.</p>"}, {"id": "FIG-1017f534fd3bcb6d", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm des LIN Network Management (<code>LinNm</code>) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die übergeordneten Betriebsmodi des LIN-NM-Zustandsautomaten sowie die zustandswechselnden Ereignisse, Bedingungen und Benachrichtigungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Zustände: <code>Bus Sleep Mode</code>, <code>Network Mode</code>.\n</li><li>Pseudozustände: Initialzustand <code>Power ON</code> (ausgefüllter Kreis), Endzustand <code>Power OFF</code> (umrandeter Punkt).\n</li><li>API-Funktionen / Trigger / Timer-Events: <code>LinNm_Init</code>, <code>LinNm_NetworkRequest</code>, <code>LinNm_PassiveStartUp</code>, <code>LinNm_NetworkRelease</code>, <code>LinNmTimeoutTime elapsed</code>.\n</li><li>Wächterbedingung: <code>[Network not requested]</code>.\n</li><li>Benachrichtigungen / Aktionen: <code>Initialization of LinNm</code>, <code>Notify Network Mode</code>, <code>Notify Bus Sleep Mode</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Eintritt über <code>Power ON</code> mit <code>LinNm_Init</code> und Ausführung von <code>/Initialization of LinNm</code> führt in den <code>Bus Sleep Mode</code>.\n</li><li>Vom <code>Bus Sleep Mode</code> wechselt das System über <code>LinNm_PassiveStartUp</code> oder über <code>LinNm_NetworkRequest /Notify Network Mode</code> in den <code>Network Mode</code>.\n</li><li>Vom <code>Network Mode</code> führt der Aufruf <code>LinNm_NetworkRelease /Notify Bus Sleep Mode</code> zurück in den <code>Bus Sleep Mode</code>.\n</li><li>Ein automatischer Übergang von <code>Network Mode</code> in den <code>Bus Sleep Mode</code> erfolgt, wenn die Bedingung <code>[Network not requested]</code> erfüllt ist und das Ereignis <code>/LinNmTimeoutTime elapsed</code> eintritt.\n</li><li>Vom <code>Bus Sleep Mode</code> führt das Ereignis <code>Power Off</code> in den Endzustand <code>Power OFF</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die normativen Zustandsübergänge des LIN-NM. Neben der expliziten Anforderung und Freigabe durch den Kommunikationsmanager wird ein automatischer Rückfallpfad bei Ausbleiben von Netzwerkanfragen (<code>[Network not requested]</code>) nach Ablauf des konfigurierbaren Timers <code>LinNmTimeoutTime</code> vorgeschrieben. Die Notifizierungen an den ComM bzw. das NM-Interface sind synchron zu den Zustandswechseln auszuführen.</p>"}], "trans": [{"from": "FIG-a5a6eb96d2826cba", "to": "FIG-9a370cb9e0009c0d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neuer Zustandsübergang von <code>Network Mode</code> nach <code>Bus Sleep Mode</code> mit Wächterbedingung <code>[Network not requested]</code> und Trigger/Aktion <code>/LinNmTimeoutTime elapsed</code>.\n</li><li>Modifizierte Syntax für Transitionen: Umstellung der Aktionen von Klammernotation <code>(Notify Bus Sleep Mode)</code> bzw. <code>(Notify Network Mode)</code> auf standardkonformen Schrägstrich <code>/Notify Bus Sleep Mode</code> und <code>/Notify Network Mode</code>.\n</li><li>Korrigierte Schreibweise des Initialisierungsaufrufs: <code>LinNm_Init /Initialization of LinNm</code> (zuvor <code>LinNm_init /Initialization of Lin NM</code>).\n</li><li>Entfernung des UML-Rahmens <code>class Activity</code> und Umstellung der Pfeile von gestrichelten Linien auf durchgezogene Linien.\n</li></ul>"}, {"from": "FIG-9a370cb9e0009c0d", "to": "FIG-1017f534fd3bcb6d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
